#include <iostream>

using namespace std;

int main()
{
    int mas[100];
    cin >> mas[1] >> mas[2] >> mas[3];

    if (mas[2] == 1)
    {
        cout << "(" << 1 << ")";
        int i = 0;
        int b = mas[2];

        while (i < mas[3])
        {
            b++;
            cout << " " << b;
            i++;
        }

        if (b < mas[1])
            cout << " >> ";
    }
    else if (mas[1] == mas[2])
    {
        int z = mas[1] - mas[3];
        cout << "<< ";

        while (z < mas[1])
        {
            if (z > 0)
                cout << z << " ";
            z++;
        }

        cout << "(" << mas[1] << ")";
    }
    else if (mas[2] < mas[1])
    {
        int c = mas[2] - mas[3];

        if (c > 1)
            cout << "<<";

        while (c < mas[2])
        {
            if (c > 0)
                cout << " " << c;
            c++;
        }

        cout << " (" << mas[2] << ")";

        int a = 0;
        while (a < mas[3] && mas[2] < mas[1])
        {
            mas[2]++;
            cout << " " << mas[2];
            a++;
        }

        if (mas[2] < mas[1])
            cout << " >> ";
    }

    return 0;
}

